INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des cultures aborigènes', 'developpement-cultures-aborigenes-australie-AU', '0001-01-01', '1700-01-01', 'Les peuples aborigènes développent une grande diversité de cultures, de langues et de traditions à travers le continent australien.', NULL, 17),
('Développement des échanges entre peuples aborigènes', 'developpement-echanges-aborigenes-australie-AU', '0001-01-01', '1700-01-01', 'Des réseaux d’échanges relient les communautés australiennes et permettent la circulation d’objets, de ressources et de pratiques culturelles.', NULL, 25),
('Arrivée des navigateurs européens sur les côtes australiennes', 'arrivee-navigateurs-europeens-australie-AU', '1606-01-01', '1606-01-01', 'Les premières expéditions européennes documentées atteignent les côtes de l’Australie au début du XVIIe siècle.', NULL, 18),
('Exploration de la côte australienne par Abel Tasman', 'exploration-abel-tasman-australie-AU', '1642-01-01', '1644-01-01', 'Abel Tasman explore plusieurs régions de l’Australie et de son environnement maritime.', NULL, 18),
('Exploration de la côte orientale par James Cook', 'exploration-james-cook-cote-est-australie-AU', '1770-04-19', '1770-08-22', 'James Cook cartographie une grande partie de la côte orientale et revendique le territoire pour la Grande-Bretagne.', NULL, 18),
('Fondation de la colonie de Nouvelle-Galles du Sud', 'fondation-nouvelle-galles-du-sud-australie-AU', '1788-01-26', '1788-01-26', 'La première colonie britannique permanente en Australie est établie à Sydney Cove.', NULL, 16),
('Début de la colonisation britannique de l’Australie', 'debut-colonisation-britannique-australie-AU', '1788-01-26', '1788-01-26', 'L’établissement britannique de Nouvelle-Galles du Sud marque le début de la colonisation permanente du continent.', NULL, 16),
('Révolte de Castle Hill', 'revolte-castle-hill-australie-AU', '1804-03-04', '1804-03-05', 'Des prisonniers irlandais se révoltent contre les autorités coloniales britanniques en Nouvelle-Galles du Sud.', NULL, 9),
('Fondation de la colonie de Tasmanie', 'fondation-colonie-tasmanie-australie-AU', '1803-09-01', '1803-09-01', 'Une implantation britannique permanente est établie sur l’île de Van Diemen’s Land, devenue la Tasmanie.', NULL, 16),
('Fondation de la colonie d’Australie-Méridionale', 'fondation-australie-meridionale-AU', '1836-12-28', '1836-12-28', 'L’Australie-Méridionale devient une colonie britannique distincte.', NULL, 16),
('Ruée vers l’or australienne', 'ruee-or-australienne-AU', '1851-01-01', '1860-01-01', 'Les découvertes d’or provoquent une forte immigration et une transformation économique et démographique des colonies australiennes.', NULL, 25),
('Eurêka Stockade', 'revolte-eureka-stockade-australie-AU', '1854-12-03', '1854-12-03', 'Des mineurs de Ballarat se soulèvent contre les autorités coloniales et le système des licences minières.', NULL, 9),
('Création de la fédération australienne', 'creation-federation-australienne-AU', '1901-01-01', '1901-01-01', 'Les six colonies australiennes s’unissent pour former le Commonwealth d’Australie.', NULL, 17),
('Participation australienne à la Première Guerre mondiale', 'participation-australie-premiere-guerre-mondiale-AU', '1914-08-04', '1918-11-11', 'Les forces australiennes participent aux principaux théâtres de la Première Guerre mondiale.', NULL, 6),
('Débarquement de Gallipoli', 'bataille-gallipoli-australie-AU', '1915-04-25', '1915-04-25', 'Les forces australiennes et néo-zélandaises débarquent à Gallipoli lors de la campagne alliée contre l’Empire ottoman.', NULL, 7),
('Statut de Westminster et autonomie australienne', 'statut-westminster-australie-AU', '1931-12-11', '1942-10-09', 'L’adoption du Statut de Westminster renforce progressivement l’autonomie constitutionnelle de l’Australie.', NULL, 22),
('Participation australienne à la Seconde Guerre mondiale', 'participation-australie-seconde-guerre-mondiale-AU', '1939-09-03', '1945-09-02', 'L’Australie participe à la Seconde Guerre mondiale sur plusieurs fronts en Europe, en Afrique et dans le Pacifique.', NULL, 6),
('Référendum australien de 1967', 'referendum-australien-1967-AU', '1967-05-27', '1967-05-27', 'Un référendum approuve massivement des changements constitutionnels concernant les populations aborigènes.', NULL, 22),
('Adoption de l’Australia Act', 'adoption-australia-act-AU', '1986-03-02', '1986-03-02', 'L’Australia Act met fin aux derniers liens constitutionnels entre l’Australie et le Parlement britannique.', NULL, 22),
('Ouverture des Jeux olympiques de Sydney', 'jeux-olympiques-sydney-australie-AU', '2000-09-15', '2000-10-01', 'Sydney accueille les Jeux olympiques d’été de 2000, événement majeur de l’histoire contemporaine australienne.', NULL, 24);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des communautés mélanésiennes aux Fidji', 'developpement-communautes-melanésiennes-fidji-FJ', '0001-01-01', '1000-01-01', 'Les populations mélanésiennes développent des communautés agricoles et maritimes dans l’archipel des Fidji.', NULL, 17),
('Développement de la navigation fidjienne', 'developpement-navigation-fidjienne-fidji-FJ', '0001-01-01', '1200-01-01', 'Les habitants des Fidji perfectionnent la navigation et les échanges entre les différentes îles de l’archipel.', NULL, 18),
('Développement de l’agriculture fidjienne', 'developpement-agriculture-fidjienne-fidji-FJ', '0500-01-01', '1500-01-01', 'L’agriculture basée notamment sur le taro, l’igname et la banane se développe dans les îles fidjiennes.', NULL, 17),
('Développement des échanges interinsulaires', 'developpement-echanges-interinsulaires-fidji-FJ', '0800-01-01', '1600-01-01', 'Les communautés fidjiennes intensifient leurs échanges de produits, d’objets et de ressources entre les îles.', NULL, 25),
('Influence tongienne aux Fidji', 'influence-tongienne-fidji-FJ', '1200-01-01', '1800-01-01', 'Les contacts avec les Tonga renforcent les échanges politiques, culturels et commerciaux dans l’est de l’archipel.', NULL, 22),
('Développement des chefferies fidjiennes', 'developpement-chefferies-fidjiennes-fidji-FJ', '1400-01-01', '1800-01-01', 'De puissantes chefferies se développent et structurent progressivement la société politique fidjienne.', NULL, 22),
('Arrivée des premiers navigateurs européens aux Fidji', 'arrivee-navigateurs-europeens-fidji-FJ', '1643-01-01', '1643-01-01', 'Abel Tasman aperçoit les îles Fidji lors de son voyage dans le Pacifique.', NULL, 18),
('Exploration européenne des Fidji', 'exploration-europeenne-fidji-FJ', '1774-01-01', '1774-01-01', 'James Cook contribue à la connaissance européenne de l’archipel fidjien lors de ses voyages dans le Pacifique.', NULL, 18),
('Développement du commerce du bois de santal', 'developpement-commerce-bois-santal-fidji-FJ', '1800-01-01', '1820-01-01', 'Le commerce du bois de santal attire des négociants étrangers et accroît les contacts avec les populations fidjiennes.', NULL, 25),
('Développement du commerce du concombre de mer', 'developpement-commerce-concombre-mer-fidji-FJ', '1820-01-01', '1850-01-01', 'Le commerce des holothuries se développe et relie davantage les Fidji aux réseaux commerciaux du Pacifique.', NULL, 25),
('Unification du royaume de Bau', 'unification-royaume-bau-fidji-FJ', '1830-01-01', '1840-01-01', 'Le royaume de Bau renforce son influence sur une grande partie de l’archipel sous la direction de puissants chefs fidjiens.', NULL, 22),
('Début du règne de Seru Epenisa Cakobau', 'regne-seru-epenisa-cakobau-fidji-FJ', '1852-01-01', '1852-01-01', 'Cakobau devient le principal dirigeant du royaume de Bau et joue un rôle majeur dans l’unification politique des Fidji.', NULL, 5),
('Cession des Fidji au Royaume-Uni', 'cession-fidji-royaume-uni-FJ', '1874-10-10', '1874-10-10', 'Cakobau et d’autres chefs fidjiens cèdent officiellement les Fidji à la Couronne britannique.', NULL, 14),
('Début de la colonie britannique des Fidji', 'fondation-colonie-britannique-fidji-FJ', '1874-10-10', '1874-10-10', 'Les Fidji deviennent une colonie britannique après leur cession à la Couronne.', NULL, 16),
('Début de l’immigration indienne aux Fidji', 'debut-immigration-indienne-fidji-FJ', '1879-05-14', '1879-05-14', 'Les premiers travailleurs sous contrat arrivent d’Inde pour travailler notamment dans les plantations de canne à sucre.', NULL, 22),
('Développement de l’industrie sucrière fidjienne', 'developpement-industrie-sucriere-fidji-FJ', '1880-01-01', '1910-01-01', 'La production de sucre devient progressivement l’un des piliers économiques de la colonie fidjienne.', NULL, 25),
('Participation des Fidji à la Seconde Guerre mondiale', 'participation-fidji-seconde-guerre-mondiale-FJ', '1939-09-03', '1945-09-02', 'Des soldats fidjiens participent aux opérations alliées dans le Pacifique pendant la Seconde Guerre mondiale.', NULL, 6),
('Indépendance des Fidji', 'independance-fidji-FJ', '1970-10-10', '1970-10-10', 'Les Fidji deviennent un État indépendant au sein du Commonwealth après la fin de la domination britannique.', NULL, 11),
('Premier coup d’État fidjien', 'premier-coup-etat-fidji-1987-FJ', '1987-05-14', '1987-05-14', 'Le lieutenant-colonel Sitiveni Rabuka renverse le gouvernement élu lors du premier coup d’État des Fidji.', NULL, 10),
('Proclamation de la République des Fidji', 'proclamation-republique-fidji-FJ', '1987-10-07', '1987-10-07', 'Les Fidji deviennent officiellement une république après l’abolition de la monarchie.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières communautés micronésiennes', 'developpement-communautes-micronesiennes-kiribati-KI', '0001-01-01', '1000-01-01', 'Les populations austronésiennes développent des communautés insulaires et des traditions maritimes dans les archipels de l’actuel Kiribati.', NULL, 17),
('Développement de la navigation dans les îles Gilbert', 'developpement-navigation-iles-gilbert-kiribati-KI', '0001-01-01', '1200-01-01', 'Les habitants perfectionnent la navigation traditionnelle entre les atolls et les îles du Pacifique central.', NULL, 18),
('Développement de l’agriculture insulaire', 'developpement-agriculture-insulaire-kiribati-KI', '0500-01-01', '1500-01-01', 'Les communautés développent la culture du cocotier, du taro et d’autres plantes adaptées aux atolls.', NULL, 17),
('Développement des échanges interinsulaires', 'developpement-echanges-interinsulaires-kiribati-KI', '0800-01-01', '1600-01-01', 'Les habitants des différents archipels renforcent leurs échanges de ressources et de produits.', NULL, 25),
('Développement des chefferies traditionnelles', 'developpement-chefferies-traditionnelles-kiribati-KI', '1000-01-01', '1700-01-01', 'Des structures politiques locales et des chefferies se développent dans les différentes îles.', NULL, 22),
('Développement des traditions maritimes gilbertines', 'developpement-traditions-maritimes-gilbertines-kiribati-KI', '1200-01-01', '1700-01-01', 'Les populations développent des techniques de navigation, de pêche et de construction de pirogues adaptées au Pacifique.', NULL, 17),
('Arrivée des premiers navigateurs européens', 'arrivee-navigateurs-europeens-kiribati-KI', '1606-01-01', '1606-01-01', 'Pedro Fernandes de Queirós et d’autres navigateurs européens contribuent aux premiers contacts européens avec les îles de la région.', NULL, 18),
('Exploration européenne des îles Gilbert', 'exploration-europeenne-iles-gilbert-kiribati-KI', '1788-01-01', '1788-01-01', 'Les navigateurs européens commencent à cartographier plus précisément les îles Gilbert.', NULL, 18),
('Développement des contacts avec les baleiniers', 'developpement-contacts-baleiniers-kiribati-KI', '1820-01-01', '1850-01-01', 'Les navires baleiniers fréquentent davantage les îles Gilbert et intensifient les contacts avec les populations locales.', NULL, 25),
('Arrivée des missionnaires chrétiens', 'arrivee-missionnaires-chretiens-kiribati-KI', '1857-01-01', '1857-01-01', 'Des missionnaires protestants commencent à s’établir dans les îles Gilbert et à diffuser le christianisme.', NULL, 23),
('Développement du christianisme aux îles Gilbert', 'developpement-christianisme-iles-gilbert-kiribati-KI', '1860-01-01', '1900-01-01', 'Le christianisme se diffuse progressivement dans l’archipel et transforme la vie religieuse et sociale.', NULL, 23),
('Établissement du protectorat britannique', 'protectorat-britannique-iles-gilbert-kiribati-KI', '1892-05-27', '1892-05-27', 'Les îles Gilbert deviennent un protectorat britannique.', NULL, 22),
('Création de la colonie des îles Gilbert et Ellice', 'creation-colonie-gilbert-ellice-kiribati-KI', '1916-01-01', '1916-01-01', 'Les îles Gilbert et Ellice sont regroupées au sein d’une colonie britannique.', NULL, 16),
('Occupation japonaise des îles Gilbert', 'occupation-japonaise-iles-gilbert-kiribati-KI', '1941-12-10', '1943-11-20', 'Les forces japonaises occupent plusieurs îles de l’archipel pendant la Seconde Guerre mondiale.', NULL, 13),
('Bataille de Tarawa', 'bataille-tarawa-kiribati-KI', '1943-11-20', '1943-11-23', 'Les forces américaines affrontent les forces japonaises lors de la bataille de Tarawa, l’un des combats majeurs du Pacifique.', NULL, 7),
('Autonomie interne des îles Gilbert', 'autonomie-interne-iles-gilbert-kiribati-KI', '1971-01-01', '1971-01-01', 'Les îles Gilbert obtiennent une autonomie interne accrue dans le cadre de leur évolution vers l’indépendance.', NULL, 22),
('Indépendance de Kiribati', 'independance-kiribati-KI', '1979-07-12', '1979-07-12', 'Les îles Gilbert deviennent la République indépendante de Kiribati.', NULL, 11),
('Adoption de la Constitution de Kiribati', 'adoption-constitution-kiribati-KI', '1979-07-12', '1979-07-12', 'La Constitution de la nouvelle République de Kiribati entre en vigueur au moment de l’indépendance.', NULL, 22),
('Création de la République de Kiribati', 'creation-republique-kiribati-KI', '1979-07-12', '1979-07-12', 'La République de Kiribati est officiellement établie comme État souverain.', NULL, 17),
('Adhésion de Kiribati aux Nations unies', 'adhesion-kiribati-nations-unies-KI', '1999-09-14', '1999-09-14', 'Kiribati devient membre de l’Organisation des Nations unies.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières communautés micronésiennes', 'developpement-communautes-micronesiennes-iles-marshall-MH', '0001-01-01', '1000-01-01', 'Les populations austronésiennes s’installent progressivement dans les atolls et développent des communautés insulaires.', NULL, 17),
('Développement de la navigation traditionnelle', 'developpement-navigation-traditionnelle-iles-marshall-MH', '0001-01-01', '1200-01-01', 'Les habitants développent des techniques avancées de navigation entre les nombreux atolls de l’archipel.', NULL, 18),
('Développement de l’agriculture des atolls', 'developpement-agriculture-atolls-iles-marshall-MH', '0500-01-01', '1500-01-01', 'Les communautés développent des cultures adaptées aux sols coralliens et aux ressources limitées des atolls.', NULL, 17),
('Développement des échanges interinsulaires', 'developpement-echanges-interinsulaires-iles-marshall-MH', '0800-01-01', '1600-01-01', 'Les communautés renforcent leurs échanges de ressources et de produits entre les différents atolls.', NULL, 25),
('Développement des chefferies traditionnelles', 'developpement-chefferies-traditionnelles-iles-marshall-MH', '1000-01-01', '1700-01-01', 'Des structures politiques fondées sur les chefferies et les clans se développent dans l’archipel.', NULL, 22),
('Développement des traditions maritimes marshallaises', 'developpement-traditions-maritimes-marshallaises-iles-marshall-MH', '1200-01-01', '1700-01-01', 'Les habitants perfectionnent la construction de pirogues et les techniques de navigation océanique.', NULL, 17),
('Arrivée des navigateurs européens dans les îles Marshall', 'arrivee-navigateurs-europeens-iles-marshall-MH', '1529-08-21', '1529-08-21', 'Le navigateur espagnol Álvaro de Saavedra découvre plusieurs îles de l’archipel lors d’une expédition dans le Pacifique.', NULL, 18),
('Exploration espagnole des îles Marshall', 'exploration-espagnole-iles-marshall-MH', '1529-01-01', '1595-01-01', 'Les navigateurs espagnols poursuivent l’exploration et la cartographie de différentes îles du Pacifique central.', NULL, 18),
('Exploration britannique des îles Marshall', 'exploration-britannique-iles-marshall-MH', '1788-01-01', '1788-01-01', 'Les expéditions britanniques contribuent à améliorer la connaissance géographique de l’archipel.', NULL, 18),
('Arrivée des missionnaires chrétiens', 'arrivee-missionnaires-chretiens-iles-marshall-MH', '1857-01-01', '1857-01-01', 'Des missionnaires protestants commencent à s’installer dans les îles Marshall et à diffuser le christianisme.', NULL, 23),
('Développement du christianisme aux îles Marshall', 'developpement-christianisme-iles-marshall-MH', '1860-01-01', '1900-01-01', 'Le christianisme se diffuse progressivement et transforme les pratiques religieuses et sociales de l’archipel.', NULL, 23),
('Établissement du protectorat allemand', 'protectorat-allemand-iles-marshall-MH', '1885-10-15', '1885-10-15', 'L’Empire allemand établit un protectorat sur les îles Marshall.', NULL, 22),
('Intégration des îles Marshall à la Nouvelle-Guinée allemande', 'integration-iles-marshall-nouvelle-guinee-allemande-MH', '1886-01-01', '1886-01-01', 'Les îles Marshall sont administrées dans le cadre de l’empire colonial allemand du Pacifique.', NULL, 22),
('Occupation japonaise des îles Marshall', 'occupation-japonaise-iles-marshall-MH', '1914-10-03', '1914-10-03', 'Le Japon prend le contrôle des îles Marshall pendant la Première Guerre mondiale.', NULL, 13),
('Mandat japonais sur les îles Marshall', 'mandat-japonais-iles-marshall-MH', '1920-12-17', '1920-12-17', 'La Société des Nations confie officiellement au Japon le mandat sur les anciennes possessions allemandes du Pacifique.', NULL, 22),
('Campagne des îles Marshall', 'campagne-iles-marshall-seconde-guerre-mondiale-MH', '1944-01-31', '1944-02-07', 'Les forces américaines prennent plusieurs positions japonaises lors de la campagne des îles Marshall.', NULL, 7),
('Administration américaine des îles Marshall', 'administration-americaine-iles-marshall-MH', '1947-07-18', '1947-07-18', 'Les îles Marshall deviennent partie du Territoire sous tutelle des îles du Pacifique administré par les États-Unis.', NULL, 22),
('Indépendance en libre association des îles Marshall', 'independance-libre-association-iles-marshall-MH', '1986-10-21', '1986-10-21', 'Les îles Marshall deviennent un État souverain en libre association avec les États-Unis.', NULL, 11),
('Adoption de la Constitution des îles Marshall', 'adoption-constitution-iles-marshall-MH', '1979-05-01', '1979-05-01', 'La Constitution entre en vigueur et établit les institutions de la République des îles Marshall.', NULL, 22),
('Adhésion des îles Marshall aux Nations unies', 'adhesion-iles-marshall-nations-unies-MH', '1991-09-17', '1991-09-17', 'Les îles Marshall deviennent membre de l’Organisation des Nations unies.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières communautés micronésiennes', 'developpement-premieres-communautes-micronesiennes-micronesie-FM', '0001-01-01', '1000-01-01', 'Les populations austronésiennes développent des communautés insulaires dans les archipels de l’actuelle Micronésie.', NULL, 17),
('Développement de la navigation océanique', 'developpement-navigation-oceanique-micronesie-FM', '0001-01-01', '1200-01-01', 'Les populations de Micronésie perfectionnent la navigation entre les îles et les atolls du Pacifique occidental.', NULL, 18),
('Développement des échanges interinsulaires', 'developpement-echanges-interinsulaires-micronesie-FM', '0500-01-01', '1500-01-01', 'Les communautés établissent des réseaux d’échanges de ressources, d’objets et de produits entre les îles.', NULL, 25),
('Développement des chefferies traditionnelles', 'developpement-chefferies-traditionnelles-micronesie-FM', '0800-01-01', '1700-01-01', 'Des structures politiques fondées sur les clans et les chefferies se développent dans plusieurs archipels.', NULL, 22),
('Développement des sociétés de Pohnpei', 'developpement-societes-pohnpei-micronesie-FM', '1000-01-01', '1500-01-01', 'Les sociétés de Pohnpei se structurent autour de chefferies et de centres politiques régionaux.', NULL, 17),
('Construction du complexe de Nan Madol', 'construction-nan-madol-micronesie-FM', '1200-01-01', '1600-01-01', 'Le complexe monumental de Nan Madol est développé sur des îlots artificiels au large de Pohnpei.', NULL, 17),
('Développement du royaume de Saudeleur', 'developpement-royaume-saudeleur-micronesie-FM', '1200-01-01', '1600-01-01', 'La dynastie Saudeleur établit un pouvoir centralisé sur une grande partie de Pohnpei.', NULL, 5),
('Arrivée des premiers navigateurs européens', 'arrivee-navigateurs-europeens-micronesie-FM', '1527-01-01', '1527-01-01', 'L’expédition espagnole de Saavedra atteint les régions de Micronésie au XVIe siècle.', NULL, 18),
('Exploration espagnole des archipels micronésiens', 'exploration-espagnole-archipels-micronesie-FM', '1527-01-01', '1595-01-01', 'Les expéditions espagnoles cartographient progressivement plusieurs îles de Micronésie.', NULL, 18),
('Développement des contacts avec les puissances européennes', 'developpement-contacts-europeens-micronesie-FM', '1600-01-01', '1800-01-01', 'Les contacts avec les navigateurs et marchands européens se multiplient dans les archipels micronésiens.', NULL, 25),
('Arrivée des missionnaires chrétiens', 'arrivee-missionnaires-chretiens-micronesie-FM', '1800-01-01', '1850-01-01', 'Des missionnaires protestants et catholiques commencent à diffuser le christianisme dans les îles de Micronésie.', NULL, 23),
('Développement du christianisme en Micronésie', 'developpement-christianisme-micronesie-FM', '1830-01-01', '1900-01-01', 'Le christianisme devient progressivement une composante majeure de la vie religieuse des populations micronésiennes.', NULL, 23),
('Établissement de la domination espagnole', 'etablissement-domination-espagnole-micronesie-FM', '1885-01-01', '1885-01-01', 'L’Espagne renforce son contrôle politique sur plusieurs territoires micronésiens.', NULL, 22),
('Cession des Carolines à l’Allemagne', 'cession-carolines-allemagne-micronesie-FM', '1899-01-01', '1899-01-01', 'L’Espagne cède les îles Carolines à l’Empire allemand, qui étend ainsi son influence dans le Pacifique.', NULL, 14),
('Occupation japonaise de la Micronésie', 'occupation-japonaise-micronesie-FM', '1914-10-01', '1914-10-01', 'Le Japon prend le contrôle de plusieurs anciennes possessions allemandes en Micronésie pendant la Première Guerre mondiale.', NULL, 13),
('Mandat japonais sur les îles du Pacifique', 'mandat-japonais-pacifique-micronesie-FM', '1920-12-17', '1920-12-17', 'La Société des Nations confie au Japon le mandat sur les anciennes possessions allemandes du Pacifique.', NULL, 22),
('Campagne du Pacifique en Micronésie', 'campagne-pacifique-micronesie-seconde-guerre-mondiale-FM', '1944-01-01', '1944-10-01', 'Les forces américaines prennent progressivement le contrôle de plusieurs territoires micronésiens pendant la Seconde Guerre mondiale.', NULL, 6),
('Création du Territoire sous tutelle des îles du Pacifique', 'creation-territoire-tutelle-iles-pacifique-micronesie-FM', '1947-07-18', '1947-07-18', 'Les territoires micronésiens placés sous administration américaine deviennent un territoire sous tutelle des Nations unies.', NULL, 16),
('Adoption du Compact de libre association', 'adoption-compact-libre-association-micronesie-FM', '1986-11-03', '1986-11-03', 'Les États fédérés de Micronésie établissent leur libre association avec les États-Unis.', NULL, 14),
('Indépendance des États fédérés de Micronésie', 'independance-etats-federes-micronesie-FM', '1986-11-03', '1986-11-03', 'Les États fédérés de Micronésie deviennent un État souverain en libre association avec les États-Unis.', NULL, 11);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières communautés nauruanes', 'developpement-premieres-communautes-nauruanes-nauru-NR', '0001-01-01', '1000-01-01', 'Des populations austronésiennes s’installent sur Nauru et développent des communautés adaptées à l’environnement insulaire.', NULL, 17),
('Développement de la navigation traditionnelle', 'developpement-navigation-traditionnelle-nauru-NR', '0001-01-01', '1200-01-01', 'Les habitants développent des techniques de navigation et entretiennent des contacts avec les autres îles du Pacifique.', NULL, 18),
('Développement des clans nauruans', 'developpement-clans-nauruans-NR', '0500-01-01', '1500-01-01', 'La société nauruane s’organise autour de clans et de communautés familiales traditionnelles.', NULL, 22),
('Développement de la pêche à Nauru', 'developpement-peche-nauru-NR', '0500-01-01', '1700-01-01', 'La pêche et l’exploitation des ressources marines deviennent essentielles à la subsistance des communautés nauruanes.', NULL, 17),
('Développement des échanges interinsulaires', 'developpement-echanges-interinsulaires-nauru-NR', '0800-01-01', '1700-01-01', 'Nauru participe à des réseaux d’échanges avec les autres populations des îles du Pacifique.', NULL, 25),
('Développement des chefferies traditionnelles', 'developpement-chefferies-traditionnelles-nauru-NR', '1000-01-01', '1800-01-01', 'Des structures sociales et politiques fondées sur les clans et les chefs locaux se consolident.', NULL, 22),
('Arrivée des navigateurs européens à Nauru', 'arrivee-navigateurs-europeens-nauru-NR', '1798-01-08', '1798-01-08', 'Le navigateur britannique John Fearn est l’un des premiers Européens à atteindre Nauru.', NULL, 18),
('Développement des contacts avec les baleiniers', 'developpement-contacts-baleiniers-nauru-NR', '1830-01-01', '1870-01-01', 'Les navires baleiniers et marchands multiplient leurs contacts avec l’île au XIXe siècle.', NULL, 25),
('Arrivée des missionnaires chrétiens', 'arrivee-missionnaires-chretiens-nauru-NR', '1887-01-01', '1887-01-01', 'Des missionnaires chrétiens commencent à s’implanter à Nauru et à diffuser leur religion.', NULL, 23),
('Développement du christianisme à Nauru', 'developpement-christianisme-nauru-NR', '1887-01-01', '1900-01-01', 'Le christianisme se diffuse progressivement dans la société nauruane.', NULL, 23),
('Établissement du protectorat allemand', 'protectorat-allemand-nauru-NR', '1888-04-16', '1888-04-16', 'L’Allemagne établit son contrôle colonial sur Nauru.', NULL, 22),
('Début de l’exploitation du phosphate', 'debut-exploitation-phosphate-nauru-NR', '1906-01-01', '1906-01-01', 'L’exploitation commerciale des importants gisements de phosphate de Nauru commence.', NULL, 25),
('Occupation australienne de Nauru', 'occupation-australienne-nauru-NR', '1914-11-06', '1914-11-06', 'Les forces australiennes prennent le contrôle de Nauru pendant la Première Guerre mondiale.', NULL, 13),
('Mandat de la Société des Nations sur Nauru', 'mandat-societe-nations-nauru-NR', '1920-12-17', '1920-12-17', 'Nauru est placé sous mandat de la Société des Nations et administré conjointement par l’Australie, la Nouvelle-Zélande et le Royaume-Uni.', NULL, 22),
('Occupation japonaise de Nauru', 'occupation-japonaise-nauru-NR', '1942-08-25', '1942-08-25', 'Les forces japonaises occupent Nauru pendant la Seconde Guerre mondiale.', NULL, 13),
('Retour de l’administration australienne', 'retour-administration-australienne-nauru-NR', '1945-09-13', '1945-09-13', 'Après la capitulation japonaise, l’administration australienne revient sur l’île.', NULL, 22),
('Création du Conseil local de Nauru', 'creation-conseil-local-nauru-NR', '1951-01-01', '1951-01-01', 'Un conseil local est créé afin d’accroître la participation des Nauruans à la gestion de leur territoire.', NULL, 17),
('Indépendance de Nauru', 'independance-nauru-NR', '1968-01-31', '1968-01-31', 'Nauru devient un État indépendant après la fin de l’administration australienne.', NULL, 11),
('Adoption de la Constitution de Nauru', 'adoption-constitution-nauru-NR', '1968-01-29', '1968-01-29', 'La Constitution de Nauru établit les institutions de la nouvelle république indépendante.', NULL, 22),
('Adhésion de Nauru aux Nations unies', 'adhesion-nauru-nations-unies-NR', '1999-09-14', '1999-09-14', 'Nauru devient membre de l’Organisation des Nations unies.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières communautés maories', 'developpement-premieres-communautes-maories-nouvelle-zelande-NZ', '1200-01-01', '1300-01-01', 'Les populations polynésiennes s’installent en Nouvelle-Zélande et développent les premières communautés maories.', NULL, 17),
('Développement de la culture maorie', 'developpement-culture-maorie-nouvelle-zelande-NZ', '1300-01-01', '1600-01-01', 'La société maorie se structure autour des iwi, hapū, traditions et pratiques culturelles propres à la Nouvelle-Zélande.', NULL, 24),
('Développement des échanges intertribaux', 'developpement-echanges-intertribaux-nouvelle-zelande-NZ', '1300-01-01', '1700-01-01', 'Les communautés maories développent des réseaux d’échanges de ressources et de biens entre les différentes régions.', NULL, 25),
('Développement des fortifications pā', 'developpement-fortifications-pa-nouvelle-zelande-NZ', '1500-01-01', '1800-01-01', 'Les communautés maories développent des fortifications pā pour protéger leurs territoires et leurs populations.', NULL, 17),
('Arrivée des Européens en Nouvelle-Zélande', 'arrivee-europeens-nouvelle-zelande-NZ', '1642-12-13', '1642-12-13', 'Abel Tasman atteint les côtes de la Nouvelle-Zélande lors de son expédition dans le Pacifique.', NULL, 18),
('Exploration de la Nouvelle-Zélande par James Cook', 'exploration-james-cook-nouvelle-zelande-NZ', '1769-10-06', '1770-03-31', 'James Cook explore et cartographie une grande partie des côtes de la Nouvelle-Zélande.', NULL, 18),
('Développement des contacts européens et maoris', 'developpement-contacts-europeens-maoris-nouvelle-zelande-NZ', '1770-01-01', '1840-01-01', 'Les échanges entre Européens et Maoris se multiplient, notamment autour du commerce et des armes.', NULL, 25),
('Arrivée des missionnaires chrétiens', 'arrivee-missionnaires-chretiens-nouvelle-zelande-NZ', '1814-12-25', '1814-12-25', 'Samuel Marsden célèbre le premier service chrétien organisé en Nouvelle-Zélande.', NULL, 23),
('Développement du christianisme en Nouvelle-Zélande', 'developpement-christianisme-nouvelle-zelande-NZ', '1814-01-01', '1850-01-01', 'Le christianisme se diffuse progressivement parmi les populations maories et les colons européens.', NULL, 23),
('Déclaration d’indépendance des tribus unies', 'declaration-independance-tribus-unies-nouvelle-zelande-NZ', '1835-10-28', '1835-10-28', 'Les chefs des tribus unies déclarent l’indépendance des tribus de Nouvelle-Zélande.', NULL, 11),
('Traité de Waitangi', 'traite-waitangi-nouvelle-zelande-NZ', '1840-02-06', '1840-02-06', 'Le traité de Waitangi est signé entre des représentants de la Couronne britannique et de nombreux chefs maoris.', NULL, 14),
('Début de la colonisation britannique', 'debut-colonisation-britannique-nouvelle-zelande-NZ', '1840-01-01', '1850-01-01', 'La colonisation britannique s’intensifie après la signature du traité de Waitangi.', NULL, 13),
('Guerres maories', 'guerres-maories-nouvelle-zelande-NZ', '1845-01-01', '1872-01-01', 'Une série de conflits oppose les forces britanniques et coloniales à plusieurs groupes maoris.', NULL, 6),
('Création de la colonie de Nouvelle-Zélande', 'creation-colonie-nouvelle-zelande-NZ', '1841-07-03', '1841-07-03', 'La Nouvelle-Zélande devient officiellement une colonie distincte de la Nouvelle-Galles du Sud.', NULL, 16),
('Obtention d’un gouvernement responsable', 'gouvernement-responsable-nouvelle-zelande-NZ', '1856-01-01', '1856-01-01', 'La Nouvelle-Zélande obtient un gouvernement responsable permettant une plus grande autonomie politique interne.', NULL, 22),
('Droit de vote des femmes en Nouvelle-Zélande', 'droit-vote-femmes-nouvelle-zelande-NZ', '1893-09-19', '1893-09-19', 'La Nouvelle-Zélande devient le premier pays autonome à accorder le droit de vote aux femmes aux élections parlementaires.', NULL, 22),
('Statut de dominion', 'statut-dominion-nouvelle-zelande-NZ', '1907-09-26', '1907-09-26', 'La Nouvelle-Zélande obtient officiellement le statut de dominion au sein de l’Empire britannique.', NULL, 22),
('Statut de Westminster', 'statut-westminster-nouvelle-zelande-NZ', '1947-11-25', '1947-11-25', 'La Nouvelle-Zélande adopte le Statut de Westminster et renforce son autonomie législative.', NULL, 22),
('Adoption de la loi constitutionnelle', 'adoption-loi-constitutionnelle-nouvelle-zelande-NZ', '1986-12-13', '1986-12-13', 'La Constitution Act de 1986 réorganise les relations constitutionnelles entre le Parlement et la Couronne.', NULL, 22),
('Accord de règlement de Waitangi', 'accord-reglement-waitangi-nouvelle-zelande-NZ', '1995-05-21', '1995-05-21', 'Le règlement historique de Waitangi reconnaît certaines injustices subies par les Ngāi Tahu et prévoit des compensations.', NULL, 14);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
