('Occupation japonaise des Palaos', 'occupation-japonaise-palaos-PW', '1914-10-01', '1914-10-01', 'Le Japon prend le contrôle des Palaos pendant la Première Guerre mondiale.', NULL, 13),
('Mandat japonais sur les Palaos', 'mandat-japonais-palaos-PW', '1920-12-17', '1920-12-17', 'La Société des Nations confie au Japon le mandat sur les anciennes possessions allemandes du Pacifique.', NULL, 22),
('Bataille de Peleliu', 'bataille-peleliu-palaos-PW', '1944-09-15', '1944-11-27', 'Les forces américaines affrontent les forces japonaises lors de la bataille de Peleliu pendant la Seconde Guerre mondiale.', NULL, 7),
('Création du Territoire sous tutelle des îles du Pacifique', 'creation-territoire-tutelle-iles-pacifique-palaos-PW', '1947-07-18', '1947-07-18', 'Les Palaos sont intégrés au Territoire sous tutelle des îles du Pacifique administré par les États-Unis.', NULL, 16),
('Adoption du Compact de libre association', 'adoption-compact-libre-association-palaos-PW', '1994-10-01', '1994-10-01', 'Le Compact de libre association avec les États-Unis entre en vigueur et accompagne l’indépendance des Palaos.', NULL, 14),
('Indépendance des Palaos', 'independance-palaos-PW', '1994-10-01', '1994-10-01', 'Les Palaos deviennent un État souverain en libre association avec les États-Unis.', NULL, 11),
('Adhésion des Palaos aux Nations unies', 'adhesion-palaos-nations-unies-PW', '1994-12-15', '1994-12-15', 'Les Palaos deviennent membre de l’Organisation des Nations unies.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
