('Arrivée des missionnaires chrétiens', 'arrivee-missionnaires-chretiens-papouasie-nouvelle-guinee-PG', '1871-01-01', '1871-01-01', 'Les premières missions chrétiennes permanentes commencent à s’implanter dans la région.', NULL, 23),
('Établissement du protectorat allemand en Nouvelle-Guinée', 'protectorat-allemand-nouvelle-guinee-PG', '1884-11-03', '1884-11-03', 'L’Allemagne établit son protectorat sur la partie nord-est de la Nouvelle-Guinée et les îles voisines.', NULL, 22),
