('Indépendance de Papouasie-Nouvelle-Guinée', 'independance-papouasie-nouvelle-guinee-PG', '1975-09-16', '1975-09-16', 'La Papouasie-Nouvelle-Guinée devient un État indépendant au sein du Commonwealth.', NULL, 11),
('Adhésion de Papouasie-Nouvelle-Guinée aux Nations unies', 'adhesion-papouasie-nouvelle-guinee-nations-unies-PG', '1975-10-10', '1975-10-10', 'La Papouasie-Nouvelle-Guinée devient membre de l’Organisation des Nations unies.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières communautés samoanes', 'developpement-premieres-communautes-samoanes-samoa-WS', '0001-01-01', '1000-01-01', 'Les populations polynésiennes s’installent dans les îles Samoa et développent des communautés organisées autour des familles et des villages.', NULL, 17),
('Développement de la navigation samoane', 'developpement-navigation-samoane-samoa-WS', '0001-01-01', '1200-01-01', 'Les habitants développent des techniques avancées de navigation et entretiennent des contacts avec les autres archipels polynésiens.', NULL, 18),
('Développement des chefferies samoanes', 'developpement-chefferies-samoanes-samoa-WS', '0500-01-01', '1500-01-01', 'Le système des matai et les structures traditionnelles de gouvernance se développent dans les villages samoans.', NULL, 22),
('Développement de la culture fa’a Samoa', 'developpement-culture-faa-samoa-samoa-WS', '0500-01-01', '1700-01-01', 'Les traditions, les liens familiaux et les institutions coutumières forment progressivement le fa’a Samoa.', NULL, 24),
('Développement des échanges interinsulaires', 'developpement-echanges-interinsulaires-samoa-WS', '0800-01-01', '1700-01-01', 'Les communautés samoanes renforcent leurs échanges avec les autres îles de Polynésie occidentale.', NULL, 25),
